import{_ as s,o as t,a as n,b as p}from"./app.DKoEZOcr.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD与SIMT混合算子性能优化","link":"/guide/operator_practice/simd_simt_hybrid_optimization/simd_simt_hybrid_optimization"},{"text":"执行控制","link":"/guide/operator_practice/simd_simt_hybrid_optimization/execution_control/thread_block_config"},{"text":"线程块数量配置优化","link":"/guide/operator_practice/simd_simt_hybrid_optimization/execution_control/thread_block_config"}]},"headers":[],"relativePath":"guide/operator_practice/simd_simt_hybrid_optimization/execution_control/thread_block_config.md","filePath":"guide/operator_practice/simd_simt_hybrid_optimization/execution_control/thread_block_config.md","lastUpdated":1787798726000}'),l={name:"guide/operator_practice/simd_simt_hybrid_optimization/execution_control/thread_block_config.md"};function c(e,a,i,d,r,o){return t(),n("div",null,[...a[0]||(a[0]=[p(`<div><article class="markdown-body"><h1>线程块数量配置优化</h1><div data-filter="950"><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 该性能优化建议适用于如下型号：</p><ul><li>Ascend 950PR/Ascend 950DT</li></ul></div></div><p>【优先级】高</p><p>【描述】SIMT kernel启动时，通过核函数（Kernel）调用符&lt;&lt;&lt;&gt;&gt;&gt;的第一个参数配置本次任务要启动的线程块数量，这些线程块需要在硬件实际存在的Vector Core（物理核）上执行。由于硬件限制，一个物理核同一时刻只能驻留并执行一个线程块，每个线程块的启动和调度都会引入固定开销。当线程块数量不超过物理核数时，所有线程块可以一次占满物理核并行执行；当线程块数量超过物理核数时，超出的线程块必须等待物理核空闲后才能被调度，调度开销随超出的线程块数量近似线性增加。因此，线程块数量应结合物理核数与数据规模设置。</p><p>物理核数可以在运行期通过<a href="https://www.hiascend.com/document/detail/zh/CANNCommunityEdition/latest/API/runtimeapi/aclcppdevg_03_1867.html">aclrtGetDeviceInfo</a>查询。在下面的场景中，实测的物理核数均为64。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 数据规模的“大”与“小”没有绝对界限，下文中的大数据量和小数据量场景只是两个量级上的代表，真正可靠的做法是以物理核数为起点实测尝试。</p><p>一个可参考的直觉是：全部物理核一次大约能并行处理“物理核数 × 单核最大线程数”个线程。数据量远大于这个量级时，将线程块数量设为物理核数就能充分发挥硬件算力；数据量与之相当甚至更小时，调度固定开销在总耗时中的占比变得敏感，最优线程块数量不再显而易见，需要使用性能工具实测。</p></div><p>确定物理核数后，还需结合数据规模来设置线程块数量。</p><p>大数据量下，线程块数量应等于物理核数。线程块数量过多会导致超出物理核数的线程块排队等待，耗时增加；线程块数量过少会导致物理核闲置、并行核数不足、单核工作量增加，并显著影响耗时。</p><p>小数据量下，每核工作量较小，启动更多核带来的调度头开销可能会反超有效并行计算的收益，最优核数往往小于物理核数。</p><p>此外，当每核实际处理的元素数小于2048时，线程数量应按每核实际处理的元素数分配，避免空转线程浪费性能。</p><p>【样例介绍】以Gather算子为例，算子功能为根据索引张量从输入张量中采集对应位置的数据写入输出，计算公式为output[i][j] = input[index[i][j]]。完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/05_simd_simt_hybrid/02_best_practices/simd_simt_grid_dim_config">线程块数量配置与vf调用优化样例</a>。</p><p>【反例】</p><p><strong>反例1：大数据量下线程块数量远超物理核数</strong></p><p>以Gather算子大数据量（index和output形状为[1024, 2048]）为例。该场景通过&lt;&lt;&lt;&gt;&gt;&gt;启动1024个线程块，远超物理核数，超出的线程块必须排队等待物理核空闲后才能被调度，代码示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 启动1024个线程块，远超物理核数</span>
<span class="n">gather_kernel</span><span class="o">&lt;&lt;&lt;</span><span class="mi">1024</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">input_device</span><span class="p">,</span><span class="w"> </span><span class="n">index_device</span><span class="p">,</span><span class="w"> </span><span class="n">output_device</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>

<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">gather_kernel</span><span class="p">(...)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">asc_vf_call</span><span class="o">&lt;</span><span class="n">simt_gather</span><span class="o">&gt;</span><span class="p">(</span><span class="n">dim3</span><span class="p">(</span><span class="mi">2048</span><span class="p">),</span><span class="w"> </span><span class="p">...,</span><span class="w"> </span><span class="n">index_total_length</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p><strong>反例2：大数据量下线程块数量低于物理核数</strong></p><p>同一大数据量下。该场景通过&lt;&lt;&lt;&gt;&gt;&gt;启动32个线程块，线程块数量仅为物理核数的一半，并行度不足，每个线程块处理的工作量翻倍，代码示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 启动32个线程块，线程块数量仅为物理核数的一半，并行度不足</span>
<span class="n">gather_kernel</span><span class="o">&lt;&lt;&lt;</span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">input_device</span><span class="p">,</span><span class="w"> </span><span class="n">index_device</span><span class="p">,</span><span class="w"> </span><span class="n">output_device</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><p><strong>反例3：小数据量下线程块数量等于物理核数</strong></p><p>以Gather算子小数据量（index和output形状为[8, 2048]）为例。该场景通过&lt;&lt;&lt;&gt;&gt;&gt;启动64个线程块（等于物理核数），但每核仅处理256个元素，增加核数带来的调度开销反超并行收益，代码示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 启动64个线程块（等于物理核数），每核处理256元素</span>
<span class="n">gather_kernel</span><span class="o">&lt;&lt;&lt;</span><span class="mi">64</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">input_device</span><span class="p">,</span><span class="w"> </span><span class="n">index_device</span><span class="p">,</span><span class="w"> </span><span class="n">output_device</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><p>【正例】</p><p><strong>正例1：大数据量下线程块数量等于物理核数</strong></p><p>大数据量下通过&lt;&lt;&lt;&gt;&gt;&gt;启动64个线程块（等于物理核数），所有线程块一次占满物理核并行执行，无需排队等待，并行度充足。代码示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 大数据量: 启动64个线程块（等于物理核数），每个线程处理16个元素</span>
<span class="n">gather_kernel</span><span class="o">&lt;&lt;&lt;</span><span class="mi">64</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">input_device</span><span class="p">,</span><span class="w"> </span><span class="n">index_device</span><span class="p">,</span><span class="w"> </span><span class="n">output_device</span><span class="p">,</span><span class="w"> </span><span class="p">...);</span>
</code></pre></div><p><strong>正例2：小数据量下实测最优核数且线程数量按实际元素数分配</strong></p><p>小数据量下通过实测性能数据得到最优核数为32。线程数量按每核实际处理元素数分配，消除空转线程，代码示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 小数据量: 启动32个线程块（实测最优），线程数量设置为512</span>
<span class="n">gather_kernel</span><span class="o">&lt;&lt;&lt;</span><span class="mi">32</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(...,</span><span class="w"> </span><span class="mi">512</span><span class="p">);</span>
</code></pre></div><p>【性能对比】</p><p><strong>大数据量（[1024, 2048]）线程块数量配置对比</strong></p><table><thead><tr><th align="center">SCENARIO_NUM</th><th align="center">线程块数量</th><th align="center">每核处理元素数</th><th align="right">Task Duration(μs)</th><th align="left">说明</th></tr></thead><tbody><tr><td align="center">9</td><td align="center">1024</td><td align="center">2048</td><td align="right">78.921</td><td align="left">线程块数量 ≫ 物理核数，排队等待</td></tr><tr><td align="center">10</td><td align="center">64</td><td align="center">32768</td><td align="right">59.109</td><td align="left">线程块数量 = 物理核数，最优</td></tr><tr><td align="center">11</td><td align="center">32</td><td align="center">65536</td><td align="right">110.540</td><td align="left">线程块数量 &lt; 物理核数，并行度不足</td></tr></tbody></table><p>大数据量下线程块数量等于物理核数时性能最优。当线程块数量为64时，既避免了过多的线程块调度开销，又能一次占满物理核并行执行，Task Duration为59.109μs，相比线程块数量为1024时下降约25.1%，相比线程块数量为32时下降约46.5%。</p><p><strong>小数据量（[8, 2048]）线程块数量与线程数量配置对比</strong></p><table><thead><tr><th align="center">SCENARIO_NUM</th><th align="center">线程块数量</th><th align="center">线程数量</th><th align="center">每核处理元素数</th><th align="right">Task Duration(μs)</th><th align="left">说明</th></tr></thead><tbody><tr><td align="center">12</td><td align="center">4</td><td align="center">2048</td><td align="center">4096</td><td align="right">10.760</td><td align="left">核数太少，单核工作量重</td></tr><tr><td align="center">13</td><td align="center">8</td><td align="center">2048</td><td align="center">2048</td><td align="right">6.741</td><td align="left">核数增加，有明显收益</td></tr><tr><td align="center">14</td><td align="center">16</td><td align="center">1024</td><td align="center">1024</td><td align="right">4.514</td><td align="left">核数增加，仍有收益</td></tr><tr><td align="center">15</td><td align="center">32</td><td align="center">512</td><td align="center">512</td><td align="right">3.866</td><td align="left">最优核数（物理核数的1/2）</td></tr><tr><td align="center">16</td><td align="center">64</td><td align="center">256</td><td align="center">256</td><td align="right">4.115</td><td align="left">等于物理核数，调度开销反超并行收益</td></tr></tbody></table><p>小数据量下线程块数量为32时性能最优，Task Duration为3.866μs。线程块数量从4增加到32的过程中耗时持续下降；线程块数量从32增加到64时耗时回升约6.4%，折线呈“先降后升”的谷形，说明小数据量下每核任务量较小，继续增加核数带来的调度开销会反超并行收益。</p><p>【总结】</p><ol><li><strong>大数据量需优先匹配物理核数</strong>：受硬件资源限制，实际可并行执行的物理核数量存在上限。线程块数量应尽量等于物理核数，避免线程块数量过多导致调度开销累积，也避免线程块数量过少导致并行度不足。</li><li><strong>小数据量需实测线程块数量性能</strong>：小数据量下每核工作量较小，启动更多线程块带来的调度头开销会反超收益，最优线程块数量往往小于物理核数。可通过分档测试寻找最优线程块数量。</li></ol></article></div>`,1)])])}const _=s(l,[["render",c]]);export{g as __pageData,_ as default};
